// ═══════════════════════════════════════════════
// Functions
// ═══════════════════════════════════════════════

export function getAnswersByCompany(companyId: string): readonly Answer[] {
  return ANSWERS.filter(a => a.companyId === companyId);
}

export function getQuestionsByChapter(chapter: string): readonly Question[] {
  return QUESTIONS.filter(q => q.chapter === chapter);
}

export function getCompanyById(companyId: string): CompanyProfile | undefined {
  return COMPANIES.find(c => c.instanceId === companyId);
}

export function getReportOutline(companyId: string): ReportOutline | undefined {
  return REPORT_OUTLINES.find(r => r.instanceId === companyId);
}

export function getEvidenceGuide(category: string): EvidenceGuide | undefined {
  return EVIDENCE_GUIDE.find(e => e.category === category);
}

export function getGRIImpact(chapter: string): GRIImpactMapping | undefined {
  return GRI_IMPACT.find(g => g.chapter === chapter);
}

